macro_rules! tests_panicking {
    () => {
        # [cfg (test)] # [cfg (not (all (target_arch = "powerpc64" , target_endian = "little")))] mod tests_panicking { extern crate std ; use super :: * ; # [cfg (f16_enabled)] macro_rules ! f16_tests { () => { # [test] fn test_f16_almost_extra_precision () { hf16 ("0x1.ffcp+0") ; } # [test] # [should_panic (expected = "the value is too precise")] fn test_f16_extra_precision () { hf16 ("0x1.ffdp+0") ; } # [test] # [should_panic (expected = "the value is too huge")] fn test_f16_overflow () { hf16 ("0x1p+16") ; } # [test] fn test_f16_tiniest () { let x = hf16 ("0x1.p-24") ; let y = hf16 ("0x0.001p-12") ; let z = hf16 ("0x0.8p-23") ; assert_eq ! (x , y) ; assert_eq ! (x , z) ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f16_too_tiny () { hf16 ("0x1.p-25") ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f16_also_too_tiny () { hf16 ("0x0.8p-24") ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f16_again_too_tiny () { hf16 ("0x0.001p-13") ; } } ; } # [cfg (f16_enabled)] f16_tests ! () ; # [test] fn test_f32_almost_extra_precision () { hf32 ("0x1.abcdeep+0") ; } # [test] # [should_panic] fn test_f32_extra_precision2 () { hf32 ("0x1.ffffffp+127") ; } # [test] # [should_panic (expected = "the value is too huge")] fn test_f32_overflow () { hf32 ("0x1p+128") ; } # [test] # [should_panic (expected = "the value is too precise")] fn test_f32_extra_precision () { hf32 ("0x1.abcdefp+0") ; } # [test] fn test_f32_tiniest () { let x = hf32 ("0x1.p-149") ; let y = hf32 ("0x0.0000000000000001p-85") ; let z = hf32 ("0x0.8p-148") ; assert_eq ! (x , y) ; assert_eq ! (x , z) ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f32_too_tiny () { hf32 ("0x1.p-150") ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f32_also_too_tiny () { hf32 ("0x0.8p-149") ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f32_again_too_tiny () { hf32 ("0x0.0000000000000001p-86") ; } # [test] fn test_f64_almost_extra_precision () { hf64 ("0x1.abcdabcdabcdfp+0") ; } # [test] # [should_panic (expected = "the value is too precise")] fn test_f64_extra_precision () { hf64 ("0x1.abcdabcdabcdf8p+0") ; } # [cfg (f128_enabled)] macro_rules ! f128_tests { () => { # [test] fn test_f128_almost_extra_precision () { hf128 ("0x1.ffffffffffffffffffffffffffffp+16383") ; } # [test] # [should_panic (expected = "the value is too precise")] fn test_f128_extra_precision () { hf128 ("0x1.fffffffffffffffffffffffffffe8p+16383") ; } # [test] # [should_panic (expected = "the value is too huge")] fn test_f128_extra_precision_overflow () { hf128 ("0x1.ffffffffffffffffffffffffffff8p+16383") ; } # [test] # [should_panic (expected = "the value is too huge")] fn test_f128_overflow () { hf128 ("0x1p+16384") ; } # [test] fn test_f128_tiniest () { let x = hf128 ("0x1.p-16494") ; let y = hf128 ("0x0.0000000000000001p-16430") ; let z = hf128 ("0x0.8p-16493") ; assert_eq ! (x , y) ; assert_eq ! (x , z) ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f128_too_tiny () { hf128 ("0x1.p-16495") ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f128_again_too_tiny () { hf128 ("0x0.0000000000000001p-16431") ; } # [test] # [should_panic (expected = "the value is too tiny")] fn test_f128_also_too_tiny () { hf128 ("0x0.8p-16494") ; } } ; } # [cfg (f128_enabled)] f128_tests ! () ; }
    };
}

tests_panicking!()